var DOCKER_WSL_INTEGRATION_CHECK = "Docker WSL integration";
var WSL_INTEGRATION_FIX = "Docker Desktop \u2192 Settings \u2192 Resources \u2192 WSL Integration \u2192 turn it on for Ubuntu \u2192 Apply & Restart\n  Verify: docker version\n  Docs: https://docs.docker.com/desktop/wsl/";
